fn main() {
    // Embed the application icon, so Explorer has something to show for the file
    // types we register. Without this the exe has no icon resource at all and
    // every registered type falls back to the generic application icon.
    //
    // An `.ico` next to the binary would not help: the shell reads the icon out
    // of the executable's resources, not the directory. `assets/app.ico` is
    // generated by `cargo run --release --example make_icon`, which is why it is
    // re-read on change rather than baked in.
    println!("cargo:rerun-if-changed=assets/app.ico");
    #[cfg(windows)]
    {
        if std::path::Path::new("assets/app.ico").exists() {
            let mut res = winresource::WindowsResource::new();
            res.set_icon("assets/app.ico");
            // Deliberately no manifest. eframe/winit sets per-monitor DPI
            // awareness through the API at startup, and a manifest that declares
            // it too can win the race and change scaling behaviour on a HiDPI
            // display - which is not something to change on faith.
            res.compile().expect("embedding the application icon");
        } else {
            // Not fatal: the build still works, files just get the generic icon.
            println!("cargo:warning=assets/app.ico is missing - run `cargo run --release --example make_icon`");
        }
    }

    // turbojpeg-sys builds libjpeg-turbo from source via CMake without setting
    // the CRT linkage, so the static turbojpeg lib comes out linked against the
    // static CRT (/MT -> LIBCMT, /MTd -> LIBCMTD). Rust MSVC binaries use the
    // dynamic CRT (/MD -> MSVCRT), and the linker warns LNK4098 about the
    // conflict. Dropping the conflicting defaultlib makes Rust's choice win.
    if std::env::var("CARGO_CFG_TARGET_ENV").as_deref() == Ok("msvc") {
        if std::env::var("DEBUG").as_deref() == Ok("true") {
            println!("cargo:rustc-link-arg=/NODEFAULTLIB:LIBCMTD");
        } else {
            println!("cargo:rustc-link-arg=/NODEFAULTLIB:LIBCMT");
        }
    }

    // `print_file` calls ShellExecuteW (the `print` verb), which lives in
    // Shell32 — not in the default link set, so without this the crate
    // compiles and then fails at link time with LNK2019.
    println!("cargo:rustc-link-lib=shell32");
    // `set_topmost` calls EnumWindows/SetWindowPos (User32), same story.
    println!("cargo:rustc-link-lib=user32");

    // Build fingerprint, shown at the bottom of Settings: short git hash plus
    // dirty flag, so a binary copied to Downloads as `image-viewer(3).exe`
    // can be told apart from the current checkout. Stale copies have already
    // caused two ghost-bug reports (a missing chord, a fixed freeze), and
    // "which build is this" should be answerable on screen, not by faith.
    println!("cargo:rerun-if-changed=.git/HEAD");
    println!("cargo:rerun-if-changed=.git/index");
    let hash = std::process::Command::new("git")
        .args(["rev-parse", "--short", "HEAD"])
        .output()
        .ok()
        .and_then(|o| String::from_utf8(o.stdout).ok())
        .map(|s| s.trim().to_owned())
        .filter(|s| !s.is_empty())
        .unwrap_or_else(|| "unknown".into());
    let dirty = std::process::Command::new("git")
        .args(["status", "--porcelain"])
        .output()
        .ok()
        .and_then(|o| String::from_utf8(o.stdout).ok())
        .map(|s| !s.trim().is_empty())
        .unwrap_or(false);
    println!("cargo:rustc-env=IV_BUILD_ID={}{}", hash, if dirty { "-dirty" } else { "" });
}
